import{d as i,u as o,m as s,e as l,c as d,w as e,r as c,o as m,j as g,a as u,_ as p}from"./index-b7d69736.js";import{P as h}from"./ProjectInfoComponent-487ae1c7.js";import"./InfoComponent-ab6184da.js";import"./Linker-acce7c84.js";/* empty css                                                               */const f=i({__name:"RLDelayedReward",setup(w){const t=o(),r=[{label:"Github",icon:"pi pi-fw pi-github",command:()=>window.open("https://github.com/Bussler/RL_With_Delayed_Reward","_blank")}],n=s([{itemImageSrc:"/images/rl-delayed-reward/result_ppo_with_lstm.gif",thumbnailImageSrc:"/images/rl-delayed-reward/result_ppo_with_lstm.gif",description:"LSTM integration in value function showing better temporal understanding and target prioritization",title:"LSTM Integration"},{itemImageSrc:"/images/rl-delayed-reward/result_ppo_no_lstm.gif",thumbnailImageSrc:"/images/rl-delayed-reward/result_ppo_no_lstm.gif",description:"Traditional feedforward networks for both policy and value functions",title:"Traditional Feedforward Networks"},{itemImageSrc:"/images/rl-delayed-reward/result_urgency_bonus.gif",thumbnailImageSrc:"/images/rl-delayed-reward/result_urgency_bonus.gif",description:"Agent trained with intermediate urgency bonuses demonstrating improved targeting",title:"Urgency Bonuses"},{itemImageSrc:"/images/rl-delayed-reward/result_only_completion.gif",thumbnailImageSrc:"/images/rl-delayed-reward/result_only_completion.gif",description:"Agent trained with purely delayed rewards showing slower convergence and suboptimal target prioritization",title:"Purely Delayed Rewards"}]);return l(async()=>{t.setToolbarComponents(r)}),(y,_)=>{const a=c("Card");return m(),d(a,null,{title:e(()=>[g("RL Delayed Reward")]),content:e(()=>[u(h,{images:n.value,about:["This project investigates reinforcement learning in environments with delayed rewards through a 3D target-catching simulation.","The experiments demonstrate that traditional delayed reward structures significantly hinder learning performance, while introducing intermediate reward signals and LSTM-enhanced value functions dramatically improves training convergence and agent effectiveness.","The simulation environment is implemented in Rust for performance optimization with a Python interface for RL training."],goal:["Explore the challenges of delayed rewards in reinforcement learning and practice Rust development.","Evaluate the impact of intermediate reward signals on learning efficiency.","Assess the benefits of LSTM networks in handling temporal dependencies within RL agents."],background:["The simulation environment consists of:","- A 3D free-moving player agent that can navigate in all directions","- Multiple enemy targets with predefined velocities or trajectory functions","- Sparse reward structure where rewards are only given upon target capture or episode completion","- Time pressure component where targets may expire if not caught within their flight time"],results:["A more thorough analysis of the results can be found in the project's GitHub repository.","In summary, the combination of intermediate rewards and LSTM-enhanced value functions outperformed the baseline delayed reward structure resulted in a faster and more stable training convergence. These results highlight the importance of:","1. Reward Function Design","Delayed vs. Intermediate Rewards: The experiments demonstrate that purely delayed reward structures hinder learning performance. Introducing intermediate reward signals showed faster convergence and higher final performance compared to the delayed-only baseline.","2. Network Architecture Impact","Incorporating Long Short-Term Memory (LSTM) networks into the value function of the Proximal Policy Optimization (PPO) algorithm yielded faster policy convergence and training acceleration:"],github:"https://github.com/Bussler/RL_With_Delayed_Reward",paper:null},null,8,["images"])]),_:1})}}});const I=p(f,[["__scopeId","data-v-0b96eb6c"]]);export{I as default};
